-- Generated by scripts/build-seed.mjs from data/seed/*.csv. Safe to re-run.

on conflict (id) do update set name = excluded.name, region = excluded.region, status = excluded.status;

on conflict (id) do update set name = excluded.name, category = excluded.category, perishability = excluded.perishability, standard_reorder_qty = excluded.standard_reorder_qty, uom = excluded.uom, distributor_id = excluded.distributor_id;

on conflict (sku_id, week) do update set units_sold = excluded.units_sold;

on conflict (sku_id) do update set location = excluded.location, units_on_hand = excluded.units_on_hand, as_of_date = excluded.as_of_date;

on conflict (year_month) do update set is_festival_month = excluded.is_festival_month;
